Gold Result:
('Christopher Rubio',)
*/

-- Prediction Query
SELECT T1.player_name FROM Player AS T1 INNER JOIN Player_Attributes AS T2 ON T1.player_api_id = T2.player_api_id ORDER BY T2.potential DESC, T1.id NULLS LAST, T2.id NULLS LAST LIMIT 1;

